const fs = require('fs');
function readStage(name) {
  let raw;
  try { raw = fs.readFileSync(name, 'utf8'); }
  catch (e) { console.error('FATAL: cannot read ' + name + ' (' + e.code + ')'); process.exit(1); }
  const value = Number(raw.trim());
  if (raw.trim() === '' || !Number.isFinite(value)) {
    console.error('FATAL: ' + name + ' is not numeric: ' + JSON.stringify(raw));
    process.exit(1);
  }
  return value;
}
const out = {
  stage1: readStage('stage1.txt'),
  stage2: readStage('stage2.txt'),
  stage3: readStage('stage3.txt'),
};
fs.writeFileSync('answer.json', JSON.stringify(out, null, 2) + '\n');
console.log('wrote answer.json =', JSON.stringify(out));
"
